        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        out = b""
        while True:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out += d
        os.waitpid(pid, 0)
        return out.decode().replace('\r','').split('\n')
    else:
        r = subprocess.run(cmd, capture_output=True)
        return r.stdout.decode().split('\n')

def budget_interval(words, observed_len):
    """words: list of words (the text). Find B such that greedy wrap with budget B puts observed_len chars on this line."""
    # greedy: add words while len(cur) + 1 + len(w) <= B
    lo = 1
    res = []
    # candidate B values: lengths at word boundaries
    cums = []
    cur = 0
    for i, w in enumerate(words):
        cur = len(w) if i == 0 else cur + 1 + len(w)
        cums.append(cur)
    obs = observed_len
    # find B range: B >= cums[k] and B < cums[k+1] where cums[k] == obs
    idx = None
    for i, c in enumerate(cums):
        if c == obs:
            idx = i
    if idx is None:
        return None
    lo = obs
    hi = cums[idx+1] - 1 if idx + 1 < len(cums) else 10**9
    return (lo, hi)
